<template><div style='display:flex;gap:8px;align-items:center;'><button @click='toggleRecording'>{{ isRecording ? "Stop" : "Record" }}</button><span v-if='isRecording'>Recording…</span></div></template><script setup lang='ts'>import { ref } from 'vue'; import { useProjectStore } from '../stores/project'; const project=useProjectStore(); const isRecording=ref(false); let mediaRecorder:MediaRecorder|null=null; let chunks:BlobPart[]=[]; async function toggleRecording(){ if(!isRecording.value){ const stream=await navigator.mediaDevices.getUserMedia({audio:true}); mediaRecorder=new MediaRecorder(stream); mediaRecorder.ondataavailable=e=>chunks.push(e.data); mediaRecorder.onstop=()=>{ const blob=new Blob(chunks,{type:'audio/webm'}); project.addTakeFromBlob(blob,'Mic Take'); chunks=[]; }; mediaRecorder.start(); isRecording.value=true; } else { mediaRecorder?.stop(); isRecording.value=false; } }</script>